contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "not enough balance to put");
        require(putAmount >= 1 ether, "put amount must be at least MinSum");

        // Setup: ensure the test contract has a Holder balance >= MinSum.
        c.Put{value: putAmount}(unlockTime);

        // Make the unlock time in the past, so Collect is allowed.
        c.Put{value: 0}(0);

        // Read the caller's recorded balance and the contract's balance before Collect.
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint cBalanceBefore = address(c).balance;

        // The accumulated balance is at least the amount put.
        require(beforeBalance >= putAmount, "balance mismatch after Put");
        require(cBalanceBefore == putAmount, "contract should hold exactly putAmount before Collect");

        // Deciding call: Collect collectAmount.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        if (!reverted) {
            // A successful Collect must have been enabled by the preconditions.
            // Exactly `collectAmount` wei must have left the contract, and the caller's
            // recorded balance must have decreased by exactly that amount.
            assert(
                collectAmount <= beforeBalance &&
                collectAmount <= cBalanceBefore &&
                cBalanceAfter == cBalanceBefore - collectAmount &&
                afterBalance == beforeBalance - collectAmount
            );
        } else {
            assert(cBalanceAfter == cBalanceBefore && afterBalance == beforeBalance);
        }
    }
}

